import unittest

from limits import accepted


class AcceptedTests(unittest.TestCase):
    def test_accepts_minimum_and_maximum(self):
        self.assertTrue(accepted(1))
        self.assertTrue(accepted(100))

    def test_accepts_values_inside_range(self):
        self.assertTrue(accepted(2))
        self.assertTrue(accepted(50))
        self.assertTrue(accepted(99))

    def test_rejects_outside_range(self):
        self.assertFalse(accepted(0))
        self.assertFalse(accepted(101))
        self.assertFalse(accepted(-1))

    def test_rejects_non_integer_values(self):
        for value in (True, False, 1.0, "1", None, [], {}):
            with self.subTest(value=value):
                self.assertFalse(accepted(value))


if __name__ == "__main__":
    unittest.main()
